import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    X = int(input_data[0])
    A = int(input_data[1])
    B = int(input_data[2])
    allowed_digits_str = input_data[3]
    allowed_digits = set(allowed_digits_str)

    def count_valid_multiples(limit):
        if limit == 0:
            return 0

        s = str(limit)
        n = len(s)
        MOD = X

        # dp[pos][tight][rem] = count
        # pos: current digit position (0 to n)
        # tight: boolean, true if we are restricted by the prefix of 'limit'
        # rem: current remainder modulo MOD

        # We will use a dictionary for the current state to save space if needed,
        # but given constraints (up to 11 digits), a fixed-size DP table is fine.
        # However, since MOD can be up to 10^11, we cannot use an array for remainder.
        # We must use a dictionary mapping remainder -> count.

        # dp[tight][rem] = count
        # Initial state: at position 0, tight=True, rem=0, count=1
        dp = {True: {0: 1}, False: {0: 1}}

        for i in range(n):
            new_dp = {}
            digit_limit = int(s[i]) if dp[True] else 9

            # Iterate over all possible previous states
            for tight_flag in [True, False]:
                current_states = dp[tight_flag]
                if not current_states:
                    continue

                # Determine the upper bound for the current digit
                upper = digit_limit if tight_flag else 9

                for rem, count in current_states.items():
                    # Try all allowed digits
                    for d_char in allowed_digits_str:
                        d = int(d_char)
                        if d > upper:
                            continue

                        new_tight = tight_flag and (d == upper)
                        new_rem = (rem * 10 + d) % MOD

                        if new_tight in new_dp:
                            if new_rem in new_dp[new_tight]:
                                new_dp[new_tight][new_rem] += count
                            else:
                                new_dp[new_tight][new_rem] = count
                        else:
                            new_dp[new_tight] = {new_rem: count}

            dp = new_dp

        # Sum up counts for all remainders == 0 in both tight states
        total = 0
        for tight_flag in [True, False]:
            if tight_flag in dp:
                if 0 in dp[tight_flag]:
                    total += dp[tight_flag][0]

        return total

    ans = count_valid_multiples(B) - count_valid_multiples(A - 1)
    print(ans)

if __name__ == "__main__":
    solve()
